import { mkdirSync, readFileSync, realpathSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const SCRIPT_PATH = fileURLToPath(import.meta.url);
const SCRIPT_DIR = dirname(SCRIPT_PATH);
const OUTPUT_PATH = resolve(SCRIPT_DIR, '../src/geometry/kernels.generated.ts');

const HEADER_LINES = [
  '// This file is generated by functions/scripts/gen-kernels.mjs. Do not edit it.',
  '/**',
  ' * Allocation-free fixed-size kernels for 2-vectors, 3-vectors, quaternions and',
  ' * 3x3 matrices. Each kernel writes into a caller-supplied `out` at an offset and',
  ' * makes no allocation, so a solver loop can call it without garbage.',
  ' *',
  ' * - A kernel accepts `number[]` and `Float64Array`. Pass one array type at a',
  ' *   call site so that the call stays monomorphic.',
  ' * - A kernel checks no bounds. A typed array drops a write past its end; a',
  ' *   `number[]` grows.',
  ' * - A kernel reads all of its inputs before it writes, so `out` can be an input.',
  ' * - A quaternion is `[w, x, y, z]`, as in the quaternion functions.',
  ' * - A 3x3 matrix is column-major: element (row r, column c) is `m[c * 3 + r]`.',
  ' * - A degenerate input gives NaN or an infinite value, in some or all components.',
  ' *   A kernel does not throw.',
  ' *',
  ' * @packageDocumentation',
  ' */',
  '',
  '/** An array that a kernel reads. */',
  'export type KernelInput = ArrayLike<number>;',
  '/** An array that a kernel writes. */',
  'export type KernelOutput = { [i: number]: number };',
  'type In = KernelInput;',
  'type Out = KernelOutput;',
  '',
  '/** Lower bound of the sum of squares for the plain square root. */',
  'const SUM_SQ_MIN = 1e-280;',
  '/** Upper bound of the sum of squares for the plain square root. */',
  'const SUM_SQ_MAX = 1e280;',
];

const HEADER = HEADER_LINES.join('\n');

function sumSqExpr(name, size) {
  let expr = '0 + ' + name + '0 * ' + name + '0';
  for (let i = 1; i < size; i += 1) {
    expr += ' + ' + name + i + ' * ' + name + i;
  }
  return expr;
}

function sqrtExpr(sumSqName, inputName, size) {
  const args = [];
  for (let i = 0; i < size; i += 1) {
    args.push(inputName + i);
  }
  return (
    sumSqName +
    ' > SUM_SQ_MIN && ' +
    sumSqName +
    ' < SUM_SQ_MAX ? Math.sqrt(' +
    sumSqName +
    ') : Math.hypot(' +
    args.join(', ') +
    ')'
  );
}

function buildRows() {
  const rows = [];

  for (const n of [2, 3]) {
    const size = n;
    const addOut = [];
    const subOut = [];
    const scaleOut = [];
    const scaleAndAddOut = [];
    const normalizeOut = [];

    for (let c = 0; c < size; c += 1) {
      addOut.push('a' + c + ' + b' + c);
      subOut.push('a' + c + ' - b' + c);
      scaleOut.push('s * a' + c);
      scaleAndAddOut.push('a' + c + ' + s * b' + c);
      normalizeOut.push('a' + c + ' / m');
    }

    let dotValue = '0 + a0 * b0';
    for (let c = 1; c < size; c += 1) {
      dotValue += ' + a' + c + ' * b' + c;
    }

    const lengthPrelude = 'const sumSq = ' + sumSqExpr('a', size) + ';';
    const lengthValue = sqrtExpr('sumSq', 'a', size);

    rows.push({
      name: 'vec' + n + 'Add',
      doc: 'Adds two ' + n + '-vectors component-wise.',
      arrays: [
        { name: 'a', size },
        { name: 'b', size },
      ],
      scalars: [],
      scalarDocs: {},
      returns: 'out',
      prelude: [],
      out: addOut,
    });

    rows.push({
      name: 'vec' + n + 'Sub',
      doc: 'Subtracts `b` from `a` component-wise.',
      arrays: [
        { name: 'a', size },
        { name: 'b', size },
      ],
      scalars: [],
      scalarDocs: {},
      returns: 'out',
      prelude: [],
      out: subOut,
    });

    rows.push({
      name: 'vec' + n + 'Scale',
      doc: 'Scales a ' + n + '-vector by a scalar.',
      arrays: [{ name: 'a', size }],
      scalars: ['s'],
      scalarDocs: { s: 'Scale factor.' },
      returns: 'out',
      prelude: [],
      out: scaleOut,
    });

    rows.push({
      name: 'vec' + n + 'ScaleAndAdd',
      doc: 'Adds `s * b` to `a` component-wise.',
      arrays: [
        { name: 'a', size },
        { name: 'b', size },
      ],
      scalars: ['s'],
      scalarDocs: { s: 'Scale factor for `b`.' },
      returns: 'out',
      prelude: [],
      out: scaleAndAddOut,
    });

    rows.push({
      name: 'vec' + n + 'Dot',
      doc: 'Computes the dot product of two ' + n + '-vectors.',
      arrays: [
        { name: 'a', size },
        { name: 'b', size },
      ],
      scalars: [],
      scalarDocs: {},
      returns: 'number',
      prelude: [],
      value: dotValue,
      returnsDoc: 'The dot product',
    });

    rows.push({
      name: 'vec' + n + 'Length',
      doc: 'Computes the length of a ' + n + '-vector.',
      arrays: [{ name: 'a', size }],
      scalars: [],
      scalarDocs: {},
      returns: 'number',
      prelude: [lengthPrelude],
      value: lengthValue,
      returnsDoc: 'The length',
    });

    rows.push({
      name: 'vec' + n + 'Normalize',
      doc: 'Normalizes a ' + n + '-vector to unit length.',
      arrays: [{ name: 'a', size }],
      scalars: [],
      scalarDocs: {},
      returns: 'out',
      prelude: [lengthPrelude, 'const m = ' + lengthValue + ';'],
      out: normalizeOut,
    });

    if (n === 3) {
      rows.push({
        name: 'vec3Cross',
        doc: 'Cross product `a × b` of two 3-vectors.',
        arrays: [
          { name: 'a', size: 3 },
          { name: 'b', size: 3 },
        ],
        scalars: [],
        scalarDocs: {},
        returns: 'out',
        prelude: [],
        out: ['a1 * b2 - a2 * b1', 'a2 * b0 - a0 * b2', 'a0 * b1 - a1 * b0'],
      });
    }
  }

  const quatSumSq = sumSqExpr('q', 4);
  const quatLength = sqrtExpr('sumSq', 'q', 4);

  rows.push({
    name: 'quatMultiply',
    doc: 'Multiplies two quaternions in Hamilton order.',
    arrays: [
      { name: 'a', size: 4 },
      { name: 'b', size: 4 },
    ],
    scalars: [],
    scalarDocs: {},
    returns: 'out',
    prelude: [],
    out: [
      'a0 * b0 - a1 * b1 - a2 * b2 - a3 * b3',
      'a0 * b1 + a1 * b0 + a2 * b3 - a3 * b2',
      'a0 * b2 - a1 * b3 + a2 * b0 + a3 * b1',
      'a0 * b3 + a1 * b2 - a2 * b1 + a3 * b0',
    ],
  });

  rows.push({
    name: 'quatConjugate',
    doc: 'Conjugates a quaternion.',
    arrays: [{ name: 'q', size: 4 }],
    scalars: [],
    scalarDocs: {},
    returns: 'out',
    prelude: [],
    out: ['q0', '-q1', '-q2', '-q3'],
  });

  rows.push({
    name: 'quatNormalize',
    doc: 'Normalizes a quaternion to unit length.',
    arrays: [{ name: 'q', size: 4 }],
    scalars: [],
    scalarDocs: {},
    returns: 'out',
    prelude: ['const sumSq = ' + quatSumSq + ';', 'const m = ' + quatLength + ';'],
    out: ['q0 / m', 'q1 / m', 'q2 / m', 'q3 / m'],
  });

  rows.push({
    name: 'quatRotate',
    doc: 'Rotates a 3-vector by a quaternion. It normalizes `q` first, using one square root and four divisions per call.',
    arrays: [
      { name: 'q', size: 4 },
      { name: 'v', size: 3 },
    ],
    scalars: [],
    scalarDocs: {},
    returns: 'out',
    prelude: [
      'const sumSq = ' + quatSumSq + ';',
      'const m = ' + quatLength + ';',
      'const u0 = q0 / m;',
      'const u1 = q1 / m;',
      'const u2 = q2 / m;',
      'const u3 = q3 / m;',
      'const z0 = 0;',
      'const p0 = u0 * z0 - u1 * v0 - u2 * v1 - u3 * v2;',
      'const p1 = u0 * v0 + u1 * z0 + u2 * v2 - u3 * v1;',
      'const p2 = u0 * v1 - u1 * v2 + u2 * z0 + u3 * v0;',
      'const p3 = u0 * v2 + u1 * v1 - u2 * v0 + u3 * z0;',
      'const k1 = -u1;',
      'const k2 = -u2;',
      'const k3 = -u3;',
      'const r1 = p0 * k1 + p1 * u0 + p2 * k3 - p3 * k2;',
      'const r2 = p0 * k2 - p1 * k3 + p2 * u0 + p3 * k1;',
      'const r3 = p0 * k3 + p1 * k2 - p2 * k1 + p3 * u0;',
    ],
    out: ['r1', 'r2', 'r3'],
  });

  rows.push({
    name: 'quatIntegrate',
    doc: 'Computes `q ← normalize(exp([0, w·dt/2]) ⊗ q)` for a world-frame angular velocity `w`. It is exact for a constant angular velocity over the step.',
    arrays: [
      { name: 'q', size: 4 },
      { name: 'w', size: 3 },
    ],
    scalars: ['dt'],
    scalarDocs: { dt: 'Time step.' },
    returns: 'out',
    prelude: [
      'const h = dt / 2;',
      'const x = w0 * h;',
      'const y = w1 * h;',
      'const z = w2 * h;',
      'const vSq = 0 + x * x + y * y + z * z;',
      'const vNorm = vSq > SUM_SQ_MIN && vSq < SUM_SQ_MAX ? Math.sqrt(vSq) : Math.hypot(x, y, z);',
      'const ew = 1;',
      'const sn = ew * Math.sin(vNorm);',
      'const s0 = vNorm === 0 ? ew : ew * Math.cos(vNorm);',
      'const s1 = vNorm === 0 ? 0 : (x / vNorm) * sn;',
      'const s2 = vNorm === 0 ? 0 : (y / vNorm) * sn;',
      'const s3 = vNorm === 0 ? 0 : (z / vNorm) * sn;',
      'const t0 = s0 * q0 - s1 * q1 - s2 * q2 - s3 * q3;',
      'const t1 = s0 * q1 + s1 * q0 + s2 * q3 - s3 * q2;',
      'const t2 = s0 * q2 - s1 * q3 + s2 * q0 + s3 * q1;',
      'const t3 = s0 * q3 + s1 * q2 - s2 * q1 + s3 * q0;',
      'const tSq = ' + sumSqExpr('t', 4) + ';',
      'const m = ' + sqrtExpr('tSq', 't', 4) + ';',
    ],
    out: ['t0 / m', 't1 / m', 't2 / m', 't3 / m'],
  });

  const mat3MultiplyOut = [];
  for (let c = 0; c < 3; c += 1) {
    for (let r = 0; r < 3; r += 1) {
      mat3MultiplyOut.push(
        `0 + a${r} * b${c * 3} + a${3 + r} * b${c * 3 + 1} + a${6 + r} * b${c * 3 + 2}`
      );
    }
  }

  rows.push({
    name: 'mat3Multiply',
    doc: 'Multiplies two 3x3 column-major matrices.',
    arrays: [
      { name: 'a', size: 9 },
      { name: 'b', size: 9 },
    ],
    scalars: [],
    scalarDocs: {},
    returns: 'out',
    prelude: [],
    out: mat3MultiplyOut,
  });

  const mat3MulVecOut = [];
  for (let r = 0; r < 3; r += 1) {
    mat3MulVecOut.push(`0 + m${r} * v0 + m${3 + r} * v1 + m${6 + r} * v2`);
  }

  rows.push({
    name: 'mat3MulVec',
    doc: 'Multiplies a 3x3 column-major matrix by a 3-vector.',
    arrays: [
      { name: 'm', size: 9 },
      { name: 'v', size: 3 },
    ],
    scalars: [],
    scalarDocs: {},
    returns: 'out',
    prelude: [],
    out: mat3MulVecOut,
  });

  const mat3TransposeOut = [];
  for (let c = 0; c < 3; c += 1) {
    for (let r = 0; r < 3; r += 1) {
      mat3TransposeOut.push(`m${r * 3 + c}`);
    }
  }

  rows.push({
    name: 'mat3Transpose',
    doc: 'Transposes a 3x3 column-major matrix.',
    arrays: [{ name: 'm', size: 9 }],
    scalars: [],
    scalarDocs: {},
    returns: 'out',
    prelude: [],
    out: mat3TransposeOut,
  });

  rows.push({
    name: 'mat3Inverse',
    doc: 'Inverts a 3x3 column-major matrix using the adjugate. An exactly singular matrix gives infinite or NaN values; a nearly singular matrix gives large finite values.',
    arrays: [{ name: 'm', size: 9 }],
    scalars: [],
    scalarDocs: {},
    returns: 'out',
    prelude: [
      'const c00 = m4 * m8 - m7 * m5;',
      'const c01 = m7 * m2 - m1 * m8;',
      'const c02 = m1 * m5 - m4 * m2;',
      'const c10 = m6 * m5 - m3 * m8;',
      'const c11 = m0 * m8 - m6 * m2;',
      'const c12 = m3 * m2 - m0 * m5;',
      'const c20 = m3 * m7 - m6 * m4;',
      'const c21 = m6 * m1 - m0 * m7;',
      'const c22 = m0 * m4 - m3 * m1;',
      'const det = m0 * c00 + m3 * c01 + m6 * c02;',
    ],
    out: [
      'c00 / det',
      'c01 / det',
      'c02 / det',
      'c10 / det',
      'c11 / det',
      'c12 / det',
      'c20 / det',
      'c21 / det',
      'c22 / det',
    ],
  });

  return rows;
}

const ROWS = buildRows();

/** Names of the emitted kernels, in emission order. */
export const KERNEL_NAMES = ROWS.map((row) => row.name);

function emitDoc(row) {
  const lines = ['/**', ' * ' + row.doc, ' *'];

  if (row.returns === 'out') {
    lines.push(
      ' * @param out - Receives the result at `outOff`. `out` can be the same array as an input.'
    );
  }

  for (let i = 0; i < row.arrays.length; i += 1) {
    const array = row.arrays[i];
    let label = 'Input';
    if (row.arrays.length > 1) {
      if (i === 0) {
        label = 'First input';
      } else if (i === 1) {
        label = 'Second input';
      } else {
        label = 'Third input';
      }
    }
    lines.push(' * @param ' + array.name + ' - ' + label + ', read at `' + array.name + 'Off`.');
  }

  for (const scalar of row.scalars) {
    lines.push(' * @param ' + scalar + ' - ' + row.scalarDocs[scalar]);
  }

  if (row.returns === 'out') {
    lines.push(' * @param outOff - Index of the first component of `out`. Default 0.');
  }

  for (const array of row.arrays) {
    lines.push(
      ' * @param ' +
        array.name +
        'Off - Index of the first component of `' +
        array.name +
        '`. Default 0.'
    );
  }

  if (row.returns === 'out') {
    lines.push(' * @returns `out`.');
  } else {
    lines.push(' * @returns ' + row.returnsDoc + '.');
  }

  lines.push(' */');
  return lines;
}

function emitFunction(row) {
  const lines = emitDoc(row);
  const params = [];

  if (row.returns === 'out') {
    params.push('out: Out');
  }

  for (const array of row.arrays) {
    params.push(array.name + ': In');
  }

  for (const scalar of row.scalars) {
    params.push(scalar + ': number');
  }

  if (row.returns === 'out') {
    params.push('outOff = 0');
  }

  for (const array of row.arrays) {
    params.push(array.name + 'Off = 0');
  }

  lines.push('export function ' + row.name + '(');
  for (let i = 0; i < params.length; i += 1) {
    const comma = i + 1 < params.length ? ',' : '';
    lines.push('  ' + params[i] + comma);
  }
  lines.push('): ' + (row.returns === 'out' ? 'Out' : 'number') + ' {');

  for (const array of row.arrays) {
    for (let i = 0; i < array.size; i += 1) {
      const index = i === 0 ? array.name + 'Off' : array.name + 'Off + ' + i;
      lines.push('  const ' + array.name + i + ' = ' + array.name + '[' + index + ']!;');
    }
  }

  for (const prelude of row.prelude) {
    lines.push('  ' + prelude);
  }

  if (row.returns === 'out') {
    for (let i = 0; i < row.out.length; i += 1) {
      const index = i === 0 ? 'outOff' : 'outOff + ' + i;
      lines.push('  out[' + index + '] = ' + row.out[i] + ';');
    }
    lines.push('  return out;');
  } else {
    lines.push('  return ' + row.value + ';');
  }

  lines.push('}');
  return lines.join('\n');
}

/**
 * Builds the text of kernels.generated.ts from the op table.
 *
 * @returns The full file text, with LF line endings and a trailing newline.
 */
export function generate() {
  const functions = [];
  for (const row of ROWS) {
    functions.push(emitFunction(row));
  }
  return HEADER + '\n\n' + functions.join('\n\n') + '\n';
}

/**
 * Finds syntax that allocates in generated kernel text: spread, `.map(`, arrow functions and
 * array destructuring.
 *
 * @param text - The generated file text.
 * @returns One message per forbidden token found; empty when the text is clean.
 */
export function staticGuard(text) {
  const forbidden = ['...', '.map(', '=>', 'const ['];
  const problems = [];
  for (const token of forbidden) {
    if (text.includes(token)) {
      problems.push('Generated text contains forbidden token: ' + token);
    }
  }
  return problems;
}

function main() {
  const args = process.argv.slice(2);
  const unknown = args.filter((arg) => arg !== '--check');
  if (unknown.length > 0) {
    console.error('Unknown argument: ' + unknown.join(' ') + '. Usage: gen-kernels.mjs [--check]');
    process.exit(2);
  }
  const text = generate();

  if (args.includes('--check')) {
    const problems = staticGuard(text);
    if (problems.length > 0) {
      console.error('Static guard failed:');
      for (const problem of problems) {
        console.error('- ' + problem);
      }
      process.exit(1);
    }

    let current;
    try {
      current = readFileSync(OUTPUT_PATH);
    } catch {
      console.error('Cannot read generated file: ' + OUTPUT_PATH);
      process.exit(1);
      return;
    }

    if (!current.equals(Buffer.from(text, 'utf8'))) {
      console.error('Generated file is out of date: ' + OUTPUT_PATH);
      process.exit(1);
      return;
    }

    return;
  }

  mkdirSync(dirname(OUTPUT_PATH), { recursive: true });
  writeFileSync(OUTPUT_PATH, text, 'utf8');
}

if (
  process.argv[1] !== undefined &&
  realpathSync(resolve(process.argv[1])) === realpathSync(SCRIPT_PATH)
) {
  main();
}
